// BannerText is the plain compact banner, for pipes and non-TTY output.
func BannerText() string { return strings.Join(compactBanner, "\n") }

// BannerColored renders the compact banner once, for `a2v banner`.
func BannerColored(phase float64) string { return strings.Join(renderArt(compactBanner, phase), "\n") }

// BannerFull renders the wide banner, for `a2v banner --full`.
func BannerFull(phase float64) string { return strings.Join(renderArt(bannerLines, phase), "\n") }

// BannerWidth is the compact banner's width.
func BannerWidth() int { return artWidth(compactBanner) }

// FullBannerWidth is the wide banner's width.
func FullBannerWidth() int { return artWidth(bannerLines) }

func artWidth(lines []string) int {
	w := 0
	for _, l := range lines {
		if n := utf8.RuneCountInString(l); n > w {
			w = n
		}
	}
	return w
}

func renderArt(lines []string, phase float64) []string {
	w := artWidth(lines)
	out := make([]string, len(lines))
	for i, line := range lines {
		out[i] = metalLine(line, i, phase, w)
	}
	return out
}
